#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "ccb_storage_supervisor.h"
static StorageWorkerEvent e(uint32_t t,uint32_t c){ StorageWorkerEvent x; storage_ipc_make_event(&x,t,c,0,0,"x"); x.result.data_persisted=x.result.receive_integrity_ok=x.result.storage_integrity_ok=x.result.integrity_ok=true; x.result.dma_received_bytes=x.result.nvme_completed_bytes=x.result.file_bytes=10; return x; }
int main(void){ StorageTaskSupervisor s; StorageWorkerEvent x; storage_supervisor_init(&s,7); x=e(STORAGE_WORKER_READY,0);assert(!storage_supervisor_handle_event(&s,&x));x=e(STORAGE_WORKER_ARMED,0);assert(!storage_supervisor_handle_event(&s,&x));x=e(STORAGE_WORKER_RUNNING,0);assert(!storage_supervisor_handle_event(&s,&x));x=e(STORAGE_WORKER_FATAL,0);assert(!storage_supervisor_handle_event(&s,&x));assert(storage_supervisor_stop_mask(&s)==7);assert(storage_supervisor_is_terminal(&s)); storage_supervisor_init(&s,1); x=e(STORAGE_WORKER_RUNNING,0);assert(storage_supervisor_handle_event(&s,&x));assert(storage_supervisor_is_terminal(&s)); storage_supervisor_init(&s,1); assert(storage_supervisor_handle_worker_eof(&s,0)); assert(storage_supervisor_is_terminal(&s)); storage_supervisor_init(&s,1); x=e(STORAGE_WORKER_FINAL_RESULT,0);assert(!storage_supervisor_handle_event(&s,&x));assert(storage_supervisor_handle_event(&s,&x)); storage_supervisor_init(&s,3); x=e(STORAGE_WORKER_FINAL_RESULT,0);assert(!storage_supervisor_handle_event(&s,&x));x=e(STORAGE_WORKER_FINAL_RESULT,1);x.result.file_bytes=x.result.nvme_completed_bytes=x.result.dma_received_bytes=11;assert(!storage_supervisor_handle_event(&s,&x));assert(storage_supervisor_result_status(&s)==STORAGE_TASK_FAILED); storage_supervisor_init(&s,3); x=e(STORAGE_WORKER_FINAL_RESULT,0);assert(!storage_supervisor_handle_event(&s,&x));x=e(STORAGE_WORKER_FINAL_RESULT,1);assert(!storage_supervisor_handle_event(&s,&x));assert(storage_supervisor_result_status(&s)==STORAGE_TASK_SUCCESS); puts("mock_storage_supervisor_test: ok"); }
